CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, suspended BOOLEAN NOT NULL DEFAULT 0, timezone VARCHAR(60) NOT NULL DEFAULT 'UTC', show_presence BOOLEAN NOT NULL DEFAULT 0, notification_preferences JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE role_memberships (user_id BIGINT UNSIGNED NOT NULL, role ENUM('buyer','seller','agent','admin','support') NOT NULL, PRIMARY KEY(user_id,role), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE rate_limits (bucket_key CHAR(64) NOT NULL, bucket BIGINT NOT NULL, hits INT NOT NULL, PRIMARY KEY(bucket_key,bucket)) ENGINE=InnoDB;
CREATE TABLE neighborhoods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, city VARCHAR(100) NOT NULL, description TEXT NOT NULL, image VARCHAR(500) NOT NULL) ENGINE=InnoDB;
CREATE TABLE agent_profiles (user_id BIGINT UNSIGNED PRIMARY KEY, biography TEXT NOT NULL, agency VARCHAR(150) NOT NULL, service_areas VARCHAR(255) NOT NULL, languages VARCHAR(255) NOT NULL DEFAULT 'English', specialties VARCHAR(255) NOT NULL DEFAULT '', photo VARCHAR(500) NOT NULL DEFAULT '', credentials TEXT NULL, contact_preferences VARCHAR(255) NOT NULL DEFAULT 'Platform messages', approved_at DATETIME NULL, verified_at DATETIME NULL, reviewed_by BIGINT UNSIGNED NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE property_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE listings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, seller_id BIGINT UNSIGNED NOT NULL, agent_id BIGINT UNSIGNED NULL, neighborhood_id BIGINT UNSIGNED NULL, title VARCHAR(190) NOT NULL, description TEXT NOT NULL, purpose ENUM('sale','rent') NOT NULL, property_type VARCHAR(80) NOT NULL, price_minor BIGINT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'USD', rental_period VARCHAR(20) NULL, bedrooms INT UNSIGNED NOT NULL, bathrooms DECIMAL(4,1) NOT NULL, floor_area DECIMAL(12,2) NOT NULL, land_area DECIMAL(12,2) NULL, area_unit ENUM('sqft','sqm') NOT NULL DEFAULT 'sqft', address VARCHAR(255) NOT NULL, city VARCHAR(100) NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, location_privacy ENUM('approximate','private','exact') NOT NULL DEFAULT 'approximate', status ENUM('draft','submitted','published','under_offer','sold','rented','rejected','withdrawn','archived') NOT NULL DEFAULT 'draft', featured BOOLEAN NOT NULL DEFAULT 0, cover_url VARCHAR(500) NOT NULL DEFAULT '', video_url VARCHAR(500) NULL, tour_url VARCHAR(500) NULL, published_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(seller_id) REFERENCES users(id), FOREIGN KEY(agent_id) REFERENCES users(id), FOREIGN KEY(neighborhood_id) REFERENCES neighborhoods(id), INDEX search_idx(status,purpose,city,price_minor), CHECK (floor_area>0), CHECK (bathrooms>=0)) ENGINE=InnoDB;
CREATE TABLE amenities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, accessibility BOOLEAN NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE listing_amenities (listing_id BIGINT UNSIGNED NOT NULL, amenity_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(listing_id,amenity_id), FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(amenity_id) REFERENCES amenities(id)) ENGINE=InnoDB;
CREATE TABLE listing_media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NOT NULL, path VARCHAR(500) NOT NULL, kind ENUM('photo','floorplan') NOT NULL DEFAULT 'photo', sort_order INT NOT NULL DEFAULT 0, is_cover BOOLEAN NOT NULL DEFAULT 0, FOREIGN KEY(listing_id) REFERENCES listings(id)) ENGINE=InnoDB;
CREATE TABLE listing_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, from_status VARCHAR(30) NOT NULL, to_status VARCHAR(30) NOT NULL, reason TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE price_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NOT NULL, price_minor BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(listing_id) REFERENCES listings(id)) ENGINE=InnoDB;
CREATE TABLE listing_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, event ENUM('view','inquiry') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(listing_id,event)) ENGINE=InnoDB;
CREATE TABLE favorites (user_id BIGINT UNSIGNED NOT NULL, listing_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,listing_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(listing_id) REFERENCES listings(id)) ENGINE=InnoDB;
CREATE TABLE collections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE collection_memberships (collection_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(collection_id,user_id), FOREIGN KEY(collection_id) REFERENCES collections(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE collection_listings (collection_id BIGINT UNSIGNED NOT NULL, listing_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(collection_id,listing_id), FOREIGN KEY(collection_id) REFERENCES collections(id), FOREIGN KEY(listing_id) REFERENCES listings(id)) ENGINE=InnoDB;
CREATE TABLE collection_comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, collection_id BIGINT UNSIGNED NOT NULL, listing_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(collection_id,listing_id) REFERENCES collection_listings(collection_id,listing_id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE saved_searches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, filters JSON NOT NULL, last_checked_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE leads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL, agent_id BIGINT UNSIGNED NOT NULL, listing_id BIGINT UNSIGNED NULL, stage ENUM('new','contacted','qualified','viewing','proposal','closed','lost') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(agent_id) REFERENCES users(id), FOREIGN KEY(listing_id) REFERENCES listings(id)) ENGINE=InnoDB;
CREATE TABLE lead_notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lead_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(lead_id) REFERENCES leads(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE lead_assignment_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lead_id BIGINT UNSIGNED NOT NULL, agent_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(lead_id) REFERENCES leads(id), FOREIGN KEY(agent_id) REFERENCES users(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, lead_id BIGINT UNSIGNED NULL, title VARCHAR(190) NOT NULL, due_at DATETIME NOT NULL, completed_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(lead_id) REFERENCES leads(id)) ENGINE=InnoDB;
CREATE TABLE availability (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, open_house BOOLEAN DEFAULT 0, UNIQUE(listing_id,starts_at), FOREIGN KEY(listing_id) REFERENCES listings(id), CHECK(ends_at>starts_at)) ENGINE=InnoDB;
CREATE TABLE viewings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, agent_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, timezone VARCHAR(60) NOT NULL, status ENUM('requested','confirmed','completed','cancelled','no_show') DEFAULT 'requested', note TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(agent_id) REFERENCES users(id), INDEX(agent_id,starts_at,ends_at), CHECK(ends_at>starts_at)) ENGINE=InnoDB;
CREATE TABLE proposals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, status ENUM('submitted','acknowledged','countered','accepted','rejected','withdrawn') DEFAULT 'submitted', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(customer_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE proposal_revisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proposal_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, amount_minor BIGINT UNSIGNED NOT NULL, terms TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(proposal_id) REFERENCES proposals(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE workflow_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, entity_type VARCHAR(30) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, state VARCHAR(40) NOT NULL, details TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(entity_type,entity_id)) ENGINE=InnoDB;
CREATE TABLE transaction_checklists (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proposal_id BIGINT UNSIGNED NOT NULL, title VARCHAR(190) NOT NULL, completed_at DATETIME NULL, FOREIGN KEY(proposal_id) REFERENCES proposals(id)) ENGINE=InnoDB;
CREATE TABLE conversations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NULL, collection_id BIGINT UNSIGNED NULL, title VARCHAR(190) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(collection_id) REFERENCES collections(id)) ENGINE=InnoDB;
CREATE TABLE conversation_participants (conversation_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, last_delivered_id BIGINT UNSIGNED NOT NULL DEFAULT 0, last_read_id BIGINT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(conversation_id,user_id), FOREIGN KEY(conversation_id) REFERENCES conversations(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conversation_id BIGINT UNSIGNED NOT NULL, sender_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, idempotency_key VARCHAR(80) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(sender_id,idempotency_key), INDEX(conversation_id,id), FOREIGN KEY(conversation_id) REFERENCES conversations(id), FOREIGN KEY(sender_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE message_receipts (message_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, delivered_at DATETIME NULL, read_at DATETIME NULL, PRIMARY KEY(message_id,user_id), FOREIGN KEY(message_id) REFERENCES messages(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE blocks (user_id BIGINT UNSIGNED NOT NULL, blocked_user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,blocked_user_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(blocked_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reporter_id BIGINT UNSIGNED NOT NULL, conversation_id BIGINT UNSIGNED NOT NULL, reason TEXT NOT NULL, status ENUM('open','reviewed','closed') DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(reporter_id) REFERENCES users(id), FOREIGN KEY(conversation_id) REFERENCES conversations(id)) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(190) NOT NULL, body TEXT NOT NULL, link VARCHAR(255) NOT NULL DEFAULT '/dashboard', read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(user_id,read_at)) ENGINE=InnoDB;
CREATE TABLE documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, listing_id BIGINT UNSIGNED NULL, message_id BIGINT UNSIGNED NULL, original_name VARCHAR(190) NOT NULL, storage_name VARCHAR(190) NOT NULL UNIQUE, mime VARCHAR(100) NOT NULL, size_bytes BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(message_id) REFERENCES messages(id)) ENGINE=InnoDB;
CREATE TABLE document_shares (document_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(document_id,user_id), FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, description TEXT NOT NULL, price_minor BIGINT UNSIGNED NOT NULL, active BOOLEAN DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE service_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, service_id BIGINT UNSIGNED NOT NULL, listing_id BIGINT UNSIGNED NULL, details TEXT NOT NULL, status ENUM('requested','quoted','scheduled','completed','cancelled') DEFAULT 'requested', quote_minor BIGINT UNSIGNED NULL, appointment_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(listing_id) REFERENCES listings(id)) ENGINE=InnoDB;
CREATE TABLE invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_id BIGINT UNSIGNED NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL, total_minor BIGINT UNSIGNED NOT NULL, currency CHAR(3) DEFAULT 'USD', status ENUM('issued','paid','credited') DEFAULT 'issued', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES service_requests(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, amount_minor BIGINT UNSIGNED NOT NULL, mode ENUM('manual','provider') DEFAULT 'manual', reference VARCHAR(190) NOT NULL UNIQUE, actor_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(actor_id) REFERENCES users(id), CHECK(amount_minor>0)) ENGINE=InnoDB;
CREATE TABLE refunds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id BIGINT UNSIGNED NOT NULL, amount_minor BIGINT UNSIGNED NOT NULL, reason TEXT NOT NULL, reference VARCHAR(190) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(payment_id) REFERENCES payments(id), CHECK(amount_minor>0)) ENGINE=InnoDB;
CREATE TABLE credits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, amount_minor BIGINT UNSIGNED NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invoice_id) REFERENCES invoices(id)) ENGINE=InnoDB;
CREATE TABLE webhook_events (provider VARCHAR(40) NOT NULL, event_id VARCHAR(190) NOT NULL, processed_at DATETIME NULL, PRIMARY KEY(provider,event_id)) ENGINE=InnoDB;
CREATE TABLE valuation_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, address VARCHAR(255) NOT NULL, property_type VARCHAR(80) NOT NULL, details TEXT NOT NULL, status ENUM('requested','assigned','completed') DEFAULT 'requested', agent_id BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(agent_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, agent_id BIGINT UNSIGNED NOT NULL, viewing_id BIGINT UNSIGNED NOT NULL UNIQUE, rating TINYINT UNSIGNED NOT NULL, body TEXT NOT NULL, status ENUM('pending','approved','rejected') DEFAULT 'pending', FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(agent_id) REFERENCES users(id), FOREIGN KEY(viewing_id) REFERENCES viewings(id), CHECK(rating BETWEEN 1 AND 5)) ENGINE=InnoDB;
CREATE TABLE content (slug VARCHAR(100) PRIMARY KEY, title VARCHAR(190) NOT NULL, body TEXT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE notification_templates (slug VARCHAR(80) PRIMARY KEY, subject VARCHAR(190) NOT NULL, body TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE delivery_failures (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, channel VARCHAR(20) NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NOT NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(50) NOT NULL, entity_id VARCHAR(100) NOT NULL, details JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(entity_type,entity_id)) ENGINE=InnoDB;
CREATE TABLE realtime_tokens (token_hash CHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
